historical.boundsHeader:
// ============================================================
// CreateWorkflow display graph bounding - 工具输出边界的有界投影
// ============================================================
// 从 create-workflow.ts 拆出：阶段词汇表让
// handler 文件越过 max-lines 上限，而裁剪本身是一段自洽的纯逻辑——分析器全图进，契约
// 形状出，无 I/O、无 memo、无端口。与 protocol-v4/create-workflow-display.ts 从
// rows.ts 拆出同一先例。
//
// 这里装的是一张**显示图**而不再是因果图的镜像。第二层是子代理导向：step 层只剩站点表
// （运行状态与检视器的键，不再画、不再带边），参与者层（每阶段的子代理卡 + 交接边）由
// 分析器的交接图投影供给、这里只做上限与转发，阶段层仍是控制流图的阶段商、仍由本层归约
// （折叠与缩点归约在 create-workflow-graph-fold.ts）。边只有 `{from, to, back?}` 一种形状；
// region / certainty / 边种类留在分析器里，GUI 从不读它们。函数名与载荷字段名沿用历史。
import { CREATE_WORKFLOW_GRAPH_MAX_HANDOFF_TYPES, CREATE_WORKFLOW_GRAPH_MAX_HANDOFFS, CREATE_WORKFLOW_GRAPH_MAX_ID_CHARS, CREATE_WORKFLOW_GRAPH_MAX_LANES, CREATE_WORKFLOW_GRAPH_MAX_NAME_CHARS, CREATE_WORKFLOW_GRAPH_MAX_PARTICIPANTS, CREATE_WORKFLOW_GRAPH_MAX_PHASE_EDGES, CREATE_WORKFLOW_GRAPH_MAX_PHASES, CREATE_WORKFLOW_GRAPH_MAX_STEPS, } from "@knorvia/contracts";
import { FLOW_ABORT, FLOW_ENTRY, FLOW_SINK, UNPHASED,
// 浏览器端回放视图直接复用本函数：走 /projections
// 子路径而非根桶，根桶会把 typescript 编译器一起拖进浏览器包。语义与根桶导出完全相同。
 } from "@knorvia/dynamic-workflow/projections";
// 阶段边的折叠与归约（含有环输入上的缩点规则）单独成模块，见该文件的文件头。
import { foldPhaseEdges } from "./create-workflow-graph-fold.js";
// display 不经过 tool result budget：图必须在进入工具输出（进而进入实时事件和持久化
// metadata）前独立限长。集合互相引用，所以裁剪顺序是固定的——先 step（源序，截尾保留
// 脚本开头），再收敛到它们引用的 lane，最后按存活的 step 过滤边与 sink。引用完整性优先
// 于保留数量：宁可少画，也不能让 UI 拿到指向不存在节点的 id。

historical.boundsTail:
// Bug 预防：actor 名 / ask label 来自脚本字符串字面量（外部输入），直接 slice 可能截断
// UTF-16 surrogate pair；与 result-display 的 MCP 文本限长同一处理——边界落在高位
// surrogate 后则丢弃半字符，保证载荷可安全序列化。id 是分析生成的 ASCII，slice 恒等通过。
function boundGraphText(value, maxChars) {
    const bounded = value.slice(0, maxChars);
    const lastCodeUnit = bounded.charCodeAt(bounded.length - 1);
    return lastCodeUnit >= 0xd800 && lastCodeUnit <= 0xdbff ? bounded.slice(0, -1) : bounded;
}
/**
 * name pattern 的限长：两个 affix 同样来自脚本字面量，走同一条 surrogate-safe 截断。
 *
 * 截断后可能一个 affix 都不剩（理论上分析器已保证非空，但契约的 min(1) 不该依赖上游的
 * 保证）——那时整个字段缺席，而不是发一个 `{}` 让 `.strict()` 通过却渲染出一个孤零零的
 * 省略号。
 */
function boundNamePattern(pattern) {
    if (pattern === undefined)
        return undefined;
    const head = pattern.head
        ? boundGraphText(pattern.head, CREATE_WORKFLOW_GRAPH_MAX_NAME_CHARS)
        : "";
    const tail = pattern.tail
        ? boundGraphText(pattern.tail, CREATE_WORKFLOW_GRAPH_MAX_NAME_CHARS)
        : "";
    if (head === "" && tail === "")
        return undefined;
    return {
        ...(head === "" ? {} : { head }),
        ...(tail === "" ? {} : { tail }),
    };
}

historical.analysis:
// ============================================================
// Workflow analysis → display - 静态分析结果到显示图 / 结果卡的唯一投影
// ============================================================
//
// 显示图由**三份**分析投影拼成：因果图给站点与车道，控制流图给阶段词汇表与阶段边，交接图给
// 每阶段的子代理卡与交接边。少传任何一份，图就静默地缺一层——中枢直接启动
// 的 run 详情侧板没有时间线、没有子代理，根因正是启动路径只传了因果图。所以「分析结果 →
// 有界显示图」只在这里拼一次；CreateWorkflow 的 handler、确认窗 gate 与直接启动三处调用它，
// 谁都不再在调用点手拼 `boundCausalityGraph(...)` 的实参。
import { CREATE_WORKFLOW_TOOL_NAME, } from "@knorvia/contracts";
import { createCreateWorkflowDisplay } from "../executor/result-display.js";
import { boundCausalityGraph } from "./create-workflow-graph-bounds.js";
/** 分析结果的有界显示图；脚本连一个站点都分析不出（编译失败早于因果图）时缺席。 */
export function boundGraphOfAnalysis(analysis) {
    return analysis.causality === undefined
        ? undefined
        : boundCausalityGraph(analysis.causality, analysis.flow, analysis.handoff);
}
/**
 * 分析结果的 `create_workflow` display（确认窗、启动轮元数据）。面向模型的 `response` 在这些
 * 读者面前没有内容——display 投影本身也不读它。AmendWorkflow 传自己的工具名：两个启动工具
 * 共用同一个 display kind。
 */
export function displayOfAnalysis(analysis, toolName = CREATE_WORKFLOW_TOOL_NAME) {
    const causalityGraph = boundGraphOfAnalysis(analysis);
    return createCreateWorkflowDisplay(toolName, {
        diagnostics: analysis.diagnostics,
        ok: analysis.ok,
        response: "",
        ...(causalityGraph === undefined ? {} : { causalityGraph }),
    });
}
